INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6155604, 907788, 64670, '<td valign="top">Fantastic point of focus!</td>', 'Fantastic point of focus!', '2010-09-08 01:20:57.000000', NULL, 1),
(6155612, 907415, 60698, '<td valign="top">Excellent capture! Love it! Should get a ribbon!</td>', 'Excellent capture! Love it! Should get a ribbon!', '2010-09-08 01:23:18.000000', NULL, 1),
(6155614, 907067, 60698, '<td valign="top">This is so weird and creative! Love it!</td>', 'This is so weird and creative! Love it!', '2010-09-08 01:24:23.000000', NULL, 1),
(6155648, 908137, 115307, '<td valign="top">This is a lovely picture. Very interesting and I would have scored it high in a free study. But it doesn''t meet the challenge for me.</td>', 'This is a lovely picture. Very interesting and I would have scored it high in a free study. But it doesn''t meet the challenge for me.', '2010-09-08 01:43:10.000000', NULL, 1),
(6155650, 908258, 115307, '<td valign="top">I am not sure I like the reflecting hood of the car. But I can tell you that I love the concept of this photo. I love how the hitchhiker appears as a ghost, to show the transient and moving nature. Great idea</td>', 'I am not sure I like the reflecting hood of the car. But I can tell you that I love the concept of this photo. I love how the hitchhiker appears as a ghost, to show the transient and moving nature. Great idea', '2010-09-08 01:45:13.000000', NULL, 1),
(6155653, 908212, 49954, '<td valign="top">Ref is part of the action...</td>', 'Ref is part of the action...', '2010-09-08 01:45:39.000000', NULL, 1),
(6155654, 907485, 115307, '<td valign="top">LOL, this is so funny. I love it. Its rare that a picture has humor AND meets the challenge AND is well photographed. This does all three. My only nitpick is that I would want more focus on the eye. But I still love it. 9</td>', 'LOL, this is so funny. I love it. Its rare that a picture has humor AND meets the challenge AND is well photographed. This does all three. My only nitpick is that I would want more focus on the eye. But I still love it. 9', '2010-09-08 01:46:38.000000', NULL, 1),
(6155663, 907788, 115307, '<td valign="top">My favorite so far. I wish the man in the wheelchair was more in focus. But this is still amazing. The symbolism is powerful and this fits the challenge perfectly</td>', 'My favorite so far. I wish the man in the wheelchair was more in focus. But this is still amazing. The symbolism is powerful and this fits the challenge perfectly', '2010-09-08 01:49:19.000000', NULL, 1),
(6155670, 907801, 115307, '<td valign="top">Perfect! This is my top shot in the challenge. I am amazed how you managed these results with Basic editing. 10</td>', 'Perfect! This is my top shot in the challenge. I am amazed how you managed these results with Basic editing. 10', '2010-09-08 01:52:04.000000', NULL, 1),
(6155674, 908081, 115307, '<td valign="top">Ooh, looks like this one is going to be a DQ. No text allowed, sorry.<br/>I like the image though, and it meets the challenge well</td>', 'Ooh, looks like this one is going to be a DQ. No text allowed, sorry.I like the image though, and it meets the challenge well', '2010-09-08 01:54:45.000000', NULL, 1),
(6155719, 908081, 37252, '<td valign="top">No text is allowed</td>', 'No text is allowed', '2010-09-08 02:29:05.000000', NULL, 1),
(6155872, 908020, 89494, '<td valign="top">it''s the best shot in the competition and even though i couldn''t find a perfect 10 between the shots i''ll rate this maximum as it is my favorite. good luck I hope you''ll win!<br/>I''m curious if it was a setup for the shot or you just captured the moment?</td>', 'it''s the best shot in the competition and even though i couldn''t find a perfect 10 between the shots i''ll rate this maximum as it is my favorite. good luck I hope you''ll win!I''m curious if it was a setup for the shot or you just captured the moment?', '2010-09-08 04:54:48.000000', NULL, 1),
(6155898, 908081, 3746, '<td valign="top">might be worth reading the rules at some point.</td>', 'might be worth reading the rules at some point.', '2010-09-08 05:25:33.000000', NULL, 1),
(6155902, 907788, 83544, '<td valign="top">Great idea for this contest but I have few remarks. I wish we can see the bystander''s face, also his head goes in the out of focus point, the strongest focus point should be completely on him, since the contest is about the bystander. The big guy above his doesn''t much contribute to the looks of the photo.</td>', 'Great idea for this contest but I have few remarks. I wish we can see the bystander''s face, also his head goes in the out of focus point, the strongest focus point should be completely on him, since the contest is about the bystander. The big guy above his doesn''t much contribute to the looks of the photo.', '2010-09-08 05:27:06.000000', NULL, 1),
(6155903, 908104, 83544, '<td valign="top">the photo doesn''t look too much artistic and the "bystander"(waiter) is actually part of the main action since he''s talking to the bartender</td>', 'the photo doesn''t look too much artistic and the "bystander"(waiter) is actually part of the main action since he''s talking to the bartender', '2010-09-08 05:27:09.000000', NULL, 1),
(6155947, 907415, 108580, '<td valign="top">Thats more like "Innocent Bystander<b>S</b>"<br/>Nice shot, what were they watching?</td>', 'Thats more like "Innocent BystanderS"Nice shot, what were they watching?', '2010-09-08 06:59:47.000000', NULL, 1),
(6155949, 908190, 108580, '<td valign="top">Unique and "cute" shot...you seldom see the little ones rear up like that. <br/>BTW the Ellie on the right entering the frame is waaaay to small to be a mom. Maybe a 2-3 year old sibling judging by the tusks and narrow head. An Elephant''s gestation period is 22 months! :) Sorry for the lecture!</td>', 'Unique and "cute" shot...you seldom see the little ones rear up like that. BTW the Ellie on the right entering the frame is waaaay to small to be a mom. Maybe a 2-3 year old sibling judging by the tusks and narrow head. An Elephant''s gestation period is 22 months! :) Sorry for the lecture!', '2010-09-08 07:06:45.000000', NULL, 1),
(6155950, 907571, 108580, '<td valign="top">Exactly! WT...</td>', 'Exactly! WT...', '2010-09-08 07:07:36.000000', NULL, 1),
(6155953, 908084, 108580, '<td valign="top">Great POV</td>', 'Great POV', '2010-09-08 07:15:29.000000', NULL, 1),
(6155955, 908276, 108580, '<td valign="top">ROFL well shot, everything just fits, expressions, weirdness...</td>', 'ROFL well shot, everything just fits, expressions, weirdness...', '2010-09-08 07:16:21.000000', NULL, 1),
(6155988, 908273, 113278, '<td valign="top">For me the image is a tad dark, allthough that may be intentional as it kinda ads to the mood and her clothing. It gives the image a Fall feel to it but I would have cropped it lower to loose the branch at the top.</td>', 'For me the image is a tad dark, allthough that may be intentional as it kinda ads to the mood and her clothing. It gives the image a Fall feel to it but I would have cropped it lower to loose the branch at the top.', '2010-09-08 08:07:28.000000', NULL, 1),
(6155991, 907434, 113278, '<td valign="top">Excellent contrasting colors and great light. Looks staged with perhaps studio lights or a flash from the catch lights in the eyes. Well done.</td>', 'Excellent contrasting colors and great light. Looks staged with perhaps studio lights or a flash from the catch lights in the eyes. Well done.', '2010-09-08 08:08:46.000000', NULL, 1),
(6155993, 908012, 113278, '<td valign="top">I think a closer crop would help here and the image seems blurry. I would have liked to see the focus on the rodeo clown and a sharper focus.</td>', 'I think a closer crop would help here and the image seems blurry. I would have liked to see the focus on the rodeo clown and a sharper focus.', '2010-09-08 08:10:05.000000', NULL, 1),
(6155998, 908272, 113278, '<td valign="top">I have a few issues with this shot. For one the bystander isn''t really viewing any action, just looking at a statue. Also th crop is weird for me, part of the base is cut off and the image is tilted. Maybe if you cut off the staue at the knees and threw it oof with some nice foreground bokeh to throw attention to the bystander, I think that would of really helped.</td>', 'I have a few issues with this shot. For one the bystander isn''t really viewing any action, just looking at a statue. Also th crop is weird for me, part of the base is cut off and the image is tilted. Maybe if you cut off the staue at the knees and threw it oof with some nice foreground bokeh to throw attention to the bystander, I think that would of really helped.', '2010-09-08 08:12:54.000000', NULL, 1),
(6156001, 907244, 113278, '<td valign="top">I think with kids you really should shoot the photo from their height. Lowering the camera to eye level or lower would add so much. Also I would have either moved myself to shoot from a different angle or moved the boy so that the bush in the background isn''t directly behind him and seemingly growing out of his shoulder.</td>', 'I think with kids you really should shoot the photo from their height. Lowering the camera to eye level or lower would add so much. Also I would have either moved myself to shoot from a different angle or moved the boy so that the bush in the background isn''t directly behind him and seemingly growing out of his shoulder.', '2010-09-08 08:15:44.000000', NULL, 1),
(6156006, 907851, 113278, '<td valign="top">Fun shot showing a bit of a story. I would prefer a straighter image and maybe even cropping down a bit to get rid of most of the sky.</td>', 'Fun shot showing a bit of a story. I would prefer a straighter image and maybe even cropping down a bit to get rid of most of the sky.', '2010-09-08 08:17:04.000000', NULL, 1),
(6156007, 907750, 113278, '<td valign="top">I like the center composition here and the contrasting light on dark and short vs. tall and small (observers) vs. large(wheel) I think there is a lot to appreciate with this shot the more it is looked upon.</td>', 'I like the center composition here and the contrasting light on dark and short vs. tall and small (observers) vs. large(wheel) I think there is a lot to appreciate with this shot the more it is looked upon.', '2010-09-08 08:19:22.000000', NULL, 1),
(6156009, 908127, 113278, '<td valign="top">The flashing strobes from the emergency vehicle gives a neat effect but there just seems to be too much going on in the shot and the bystanders are such a small part of the image.</td>', 'The flashing strobes from the emergency vehicle gives a neat effect but there just seems to be too much going on in the shot and the bystanders are such a small part of the image.', '2010-09-08 08:21:02.000000', NULL, 1),
(6156013, 907974, 62989, '<td valign="top">There is something very apealing about the colours and shapes here but it takes a second look - up to 8 fom 5</td>', 'There is something very apealing about the colours and shapes here but it takes a second look - up to 8 fom 5', '2010-09-08 08:24:43.000000', NULL, 1),
(6156014, 908030, 113278, '<td valign="top">First off Stone Sour Rocks. Ok now to the image. Sadly I do not like this image much at all and I want to, I love live music and concert photos. The crop on this is very strange with a couple of heads and hands in the crowd, part of the drum set and the camera guy(whom I suspect you are trying to portray as the innocent bystander) I imagine the crop is to try and have the bystander in the shot but I would of liked the bystander to be the main part of the composition and not just someone you think need to be cropped out.</td>', 'First off Stone Sour Rocks. Ok now to the image. Sadly I do not like this image much at all and I want to, I love live music and concert photos. The crop on this is very strange with a couple of heads and hands in the crowd, part of the drum set and the camera guy(whom I suspect you are trying to portray as the innocent bystander) I imagine the crop is to try and have the bystander in the shot but I would of liked the bystander to be the main part of the composition and not just someone you think need to be cropped out.', '2010-09-08 08:24:51.000000', NULL, 1),
(6156015, 908084, 113278, '<td valign="top">I like the different geometrical patterns, the overhead perspective, the hard shadow and the B&amp;W processing. I just like this image, if I were to suggest anything different it would be to straighten the stones on the left side of the photo so it makes a nice clear line to the subject.</td>', 'I like the different geometrical patterns, the overhead perspective, the hard shadow and the B&W processing. I just like this image, if I were to suggest anything different it would be to straighten the stones on the left side of the photo so it makes a nice clear line to the subject.', '2010-09-08 08:33:23.000000', NULL, 1),
(6156016, 907868, 113278, '<td valign="top">Well I have started commenting on all the images so no need skipping this one. I see this as a intentional shoehorn. I do not see any action, either shown or implied and I see no bystander.</td>', 'Well I have started commenting on all the images so no need skipping this one. I see this as a intentional shoehorn. I do not see any action, either shown or implied and I see no bystander.', '2010-09-08 08:35:11.000000', NULL, 1),
(6156019, 907415, 113278, '<td valign="top">Now that is a lot of bystanders. I like the framing and stacking here but I may have just gone with two levels, either that or I would like to see more of the top level. It seems tilted a bit but that may just be from shooting at an angle. More of a straight on composition would of worked so much better but that may not of been possible. Overall a pretty nice image.</td>', 'Now that is a lot of bystanders. I like the framing and stacking here but I may have just gone with two levels, either that or I would like to see more of the top level. It seems tilted a bit but that may just be from shooting at an angle. More of a straight on composition would of worked so much better but that may not of been possible. Overall a pretty nice image.', '2010-09-08 08:37:49.000000', NULL, 1),
(6156132, 907244, 33361, '<td valign="top">Title sucks!</td>', 'Title sucks!', '2010-09-08 10:38:22.000000', NULL, 1),
(6156154, 908081, 33361, '<td valign="top">Too bad you didn''t read the rules about no text. : (</td>', 'Too bad you didn''t read the rules about no text. : (', '2010-09-08 10:45:53.000000', NULL, 1),
(6156182, 907586, 113419, '<td valign="top">wonderfully done!</td>', 'wonderfully done!', '2010-09-08 10:58:49.000000', NULL, 1),
(6156183, 908202, 113419, '<td valign="top">because the boys face is lost in the background it causes a distraction for me</td>', 'because the boys face is lost in the background it causes a distraction for me', '2010-09-08 10:59:41.000000', NULL, 1),
(6156184, 908258, 118396, '<td valign="top">You''re brave standing on the side of that road!  I''ve driven around there - crazy!</td>', 'You''re brave standing on the side of that road!  I''ve driven around there - crazy!', '2010-09-08 11:00:09.000000', NULL, 1),
(6156185, 907415, 113419, '<td valign="top">great shot!  very interesting</td>', 'great shot!  very interesting', '2010-09-08 11:00:12.000000', NULL, 1),
(6156188, 908276, 113419, '<td valign="top">haha  how funny! - also a good shot and it translates well in black and white</td>', 'haha  how funny! - also a good shot and it translates well in black and white', '2010-09-08 11:01:14.000000', NULL, 1),
(6156191, 907974, 118396, '<td valign="top">Now if you were offering free samples with your photo, I''d give you bonus points!  :)  Great subject!</td>', 'Now if you were offering free samples with your photo, I''d give you bonus points!  :)  Great subject!', '2010-09-08 11:01:45.000000', NULL, 1),
(6156192, 907851, 113419, '<td valign="top">wonderful image with lots of expression even without the kids face and for me that''s what makes it good</td>', 'wonderful image with lots of expression even without the kids face and for me that''s what makes it good', '2010-09-08 11:02:10.000000', NULL, 1),
(6156194, 907985, 113419, '<td valign="top">very nice!  love the sense of mystery in this shot</td>', 'very nice!  love the sense of mystery in this shot', '2010-09-08 11:02:57.000000', NULL, 1),
(6156196, 908020, 113419, '<td valign="top">very pretty silhouette</td>', 'very pretty silhouette', '2010-09-08 11:03:37.000000', NULL, 1),
(6156248, 908274, 113278, '<td valign="top">Nice composition and color. I love how you can see the action but the focus is on the boy. Nice work.</td>', 'Nice composition and color. I love how you can see the action but the focus is on the boy. Nice work.', '2010-09-08 12:10:05.000000', NULL, 1),
(6156250, 908137, 113278, '<td valign="top">I like this photo. The look and feel of it are very nice imho but I don''t see how it fits the challenge. What action are the birds suppose to be seeing? I don''t notice any action, implied or otherwise.</td>', 'I like this photo. The look and feel of it are very nice imho but I don''t see how it fits the challenge. What action are the birds suppose to be seeing? I don''t notice any action, implied or otherwise.', '2010-09-08 12:13:44.000000', NULL, 1),
(6156252, 908064, 113278, '<td valign="top">Love the clarity and composition of the chopper. But it is the main focus. I would have liked to see the focus more on the bystander but still well done. 7</td>', 'Love the clarity and composition of the chopper. But it is the main focus. I would have liked to see the focus more on the bystander but still well done. 7', '2010-09-08 12:15:31.000000', NULL, 1),
(6156253, 908216, 113278, '<td valign="top">Beautiful. Love the processing on this and the slight bit of motion blur. Very artsy.</td>', 'Beautiful. Love the processing on this and the slight bit of motion blur. Very artsy.', '2010-09-08 12:16:19.000000', NULL, 1),
(6156254, 908279, 113278, '<td valign="top">Lovely image. Love the light on the kids face.</td>', 'Lovely image. Love the light on the kids face.', '2010-09-08 12:17:32.000000', NULL, 1),
(6156258, 908202, 113278, '<td valign="top">She just looks mad. I like the fact that you put the focus on the bystander but still had part of the action in the frame supporting the composition.</td>', 'She just looks mad. I like the fact that you put the focus on the bystander but still had part of the action in the frame supporting the composition.', '2010-09-08 12:18:53.000000', NULL, 1),
(6156263, 907485, 113278, '<td valign="top">Man it took me a second then BAM... This is going to be one that I remember. Perhaps a bit of a stretch for the challenge but creative.</td>', 'Man it took me a second then BAM... This is going to be one that I remember. Perhaps a bit of a stretch for the challenge but creative.', '2010-09-08 12:20:22.000000', NULL, 1),
(6156265, 907545, 113278, '<td valign="top">For animals and other subjects that are low to the ground I would suggest getting low with your camera. Eye level or lower with subjects like this really help the look of the shot. Also the light seems harsh, mainly due to the strong shadow cast on the wall. I would say to bounce a flash off of something or diffuse the light in some way. The crop is also a tad tight and part of the dogs ear is chopped.</td>', 'For animals and other subjects that are low to the ground I would suggest getting low with your camera. Eye level or lower with subjects like this really help the look of the shot. Also the light seems harsh, mainly due to the strong shadow cast on the wall. I would say to bounce a flash off of something or diffuse the light in some way. The crop is also a tad tight and part of the dogs ear is chopped.', '2010-09-08 12:23:18.000000', NULL, 1),
(6156267, 908068, 113278, '<td valign="top">I like the colors on this but perhaps there is too much going on? I''m not sure about that yet, I keep getting drawn to the guy with the beard and sunglasses but then the guy on the left of the shot tries to pull my eyes that way. I wonder how it would look cropping out the left. Nice work though.</td>', 'I like the colors on this but perhaps there is too much going on? I''m not sure about that yet, I keep getting drawn to the guy with the beard and sunglasses but then the guy on the left of the shot tries to pull my eyes that way. I wonder how it would look cropping out the left. Nice work though.', '2010-09-08 12:25:46.000000', NULL, 1),
(6156272, 908147, 113278, '<td valign="top">Beautiful. I love how you got down to her level to take the shot, it really adds so much and shows that you thought about what you were doing. And including part of the parade in the shot but blurred out really adds to it. The only thing I wish is that her eyes had a bit more sparkle to them.</td>', 'Beautiful. I love how you got down to her level to take the shot, it really adds so much and shows that you thought about what you were doing. And including part of the parade in the shot but blurred out really adds to it. The only thing I wish is that her eyes had a bit more sparkle to them.', '2010-09-08 12:27:35.000000', NULL, 1),
(6156273, 907739, 118396, '<td valign="top">I like the texture of the lanterns and the steam.  This really captured the meaning of the challenge.</td>', 'I like the texture of the lanterns and the steam.  This really captured the meaning of the challenge.', '2010-09-08 12:27:44.000000', NULL, 1),
(6156274, 907512, 118396, '<td valign="top">This photo really nailed the challenge, IMO.  Great capture.</td>', 'This photo really nailed the challenge, IMO.  Great capture.', '2010-09-08 12:27:46.000000', NULL, 1),
(6156276, 907067, 113278, '<td valign="top">This is, different. I enjoy looking at this though because there is so much to take in and yet I am not completely sure what it is that I am taking in. I don''t even know if this meets the challenge but the way it is done it makes me think that it does meet the challenge. It is like I see what my mind wants me to see and then makes me question wether or not I am really seeing it. Have I gone mad? 10</td>', 'This is, different. I enjoy looking at this though because there is so much to take in and yet I am not completely sure what it is that I am taking in. I don''t even know if this meets the challenge but the way it is done it makes me think that it does meet the challenge. It is like I see what my mind wants me to see and then makes me question wether or not I am really seeing it. Have I gone mad? 10', '2010-09-08 12:31:02.000000', NULL, 1),
(6156278, 907788, 113278, '<td valign="top">Brilliant shot. I love the boy smiling in the marching line, it is as though he is the past of the man in the chair. Love it.</td>', 'Brilliant shot. I love the boy smiling in the marching line, it is as though he is the past of the man in the chair. Love it.', '2010-09-08 12:32:27.000000', NULL, 1),
(6156282, 908081, 113278, '<td valign="top">Bummer about the text this is a great shot for the challenge. I would like to see the cars in the frame as well though.</td>', 'Bummer about the text this is a great shot for the challenge. I would like to see the cars in the frame as well though.', '2010-09-08 12:33:39.000000', NULL, 1),
(6156286, 908208, 113278, '<td valign="top">Nice use of B&amp;W here, but this seems to be after the fact and there is not much in the form of action. I suppose it could be said that the girl on the far right is the bystander.</td>', 'Nice use of B&W here, but this seems to be after the fact and there is not much in the form of action. I suppose it could be said that the girl on the far right is the bystander.', '2010-09-08 12:35:31.000000', NULL, 1),
(6156293, 908148, 113278, '<td valign="top">Neat image here. Love the red and red theme and the bright white of the walls. Something weird is going on where wall and floor meet. There seems to be a shadow up until you get to the front leg then there is just a line. Not sure if that was done in post or if it was like that. Normally with a pose like this I would want the subject looking into the frame and not out of it but for this challenge it leaves much to the imagination; Is she admiring a painting, a sculpture, an artist working or perhaps another person.</td>', 'Neat image here. Love the red and red theme and the bright white of the walls. Something weird is going on where wall and floor meet. There seems to be a shadow up until you get to the front leg then there is just a line. Not sure if that was done in post or if it was like that. Normally with a pose like this I would want the subject looking into the frame and not out of it but for this challenge it leaves much to the imagination; Is she admiring a painting, a sculpture, an artist working or perhaps another person.', '2010-09-08 12:40:18.000000', NULL, 1),
(6156297, 908208, 113156, '<td valign="top">Nice composition, and interesting scene.</td>', 'Nice composition, and interesting scene.', '2010-09-08 12:42:56.000000', NULL, 1),
(6156298, 908258, 113278, '<td valign="top">Ahh the long double exposure. It took me a second to notice the person and I may have missed it alltogether if I hadn''t read the title. This has an interesting tilt and I have to give you props for getting out on the shoulder on that street.</td>', 'Ahh the long double exposure. It took me a second to notice the person and I may have missed it alltogether if I hadn''t read the title. This has an interesting tilt and I have to give you props for getting out on the shoulder on that street.', '2010-09-08 12:43:08.000000', NULL, 1),
(6156303, 908127, 113156, '<td valign="top">this is a cool and interesting photo, bravo.</td>', 'this is a cool and interesting photo, bravo.', '2010-09-08 12:48:30.000000', NULL, 1),
(6156306, 908216, 113156, '<td valign="top">In my book this is number one, great black and white.</td>', 'In my book this is number one, great black and white.', '2010-09-08 12:55:46.000000', NULL, 1),
(6156311, 908084, 39679, '<td valign="top">I LOVE this perspective.  We''re always told to explore a scene from a different perspective...that normally yields the best shots and you''ve really done a great job here.  I don''t know if it was intentional but having the script in an "upright" perspective and the person not in an upright perspective really adds interest to this shot.</td>', 'I LOVE this perspective.  We''re always told to explore a scene from a different perspective...that normally yields the best shots and you''ve really done a great job here.  I don''t know if it was intentional but having the script in an "upright" perspective and the person not in an upright perspective really adds interest to this shot.', '2010-09-08 13:01:16.000000', NULL, 1),
(6156315, 907489, 39679, '<td valign="top">I really like this shot but I''m not getting the challenge from it.</td>', 'I really like this shot but I''m not getting the challenge from it.', '2010-09-08 13:04:59.000000', NULL, 1),
(6156330, 908081, 86447, '<td valign="top">Oh darn!   Good entry. I love the emotion, but... your disqualification is coming... Text is not allowed to be added to your entry.</td>', 'Oh darn!   Good entry. I love the emotion, but... your disqualification is coming... Text is not allowed to be added to your entry.', '2010-09-08 13:15:53.000000', NULL, 1),
